#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ilen = 0, ipos = 0;

static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long v = 0;
    while (c >= '0' && c <= '9') {
        v = v * 10 + (c - '0');
        c = gc();
    }
    return neg ? -v : v;
}

static string readToken() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    string s;
    while (c > ' ') {
        s.push_back((char)c);
        c = gc();
    }
    return s;
}

static const string DELETED = string(1, '\0');

int main() {
    int q = (int)readInt();
    unordered_map<string, string> base;
    vector<unordered_map<string, string>> layers;
    string out;
    for (int i = 0; i < q; i++) {
        string op = readToken();
        if (op == "SET") {
            string k = readToken(), v = readToken();
            (layers.empty() ? base : layers.back())[k] = v;
        } else if (op == "DELETE") {
            string k = readToken();
            (layers.empty() ? base : layers.back())[k] = DELETED;
        } else if (op == "GET") {
            string k = readToken();
            const string *found = nullptr;
            for (int d = (int)layers.size() - 1; d >= 0 && !found; d--) {
                auto it = layers[d].find(k);
                if (it != layers[d].end()) found = &it->second;
            }
            if (!found) {
                auto it = base.find(k);
                if (it != base.end()) found = &it->second;
            }
            out += (!found || *found == DELETED) ? "NULL" : *found;
            out.push_back('\n');
        } else if (op == "BEGIN") {
            layers.emplace_back();
        } else if (op == "ROLLBACK") {
            if (layers.empty()) out += "NO TRANSACTION\n";
            else layers.pop_back();
        } else if (op == "COMMIT") {
            if (layers.empty()) out += "NO TRANSACTION\n";
            else {
                auto top = move(layers.back());
                layers.pop_back();
                auto &parent = layers.empty() ? base : layers.back();
                for (auto &kv : top) parent[kv.first] = move(kv.second);
            }
        }
    }
    fputs(out.c_str(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static final String DELETED = "\0";

    public static void main(String[] args) throws IOException {
        int q = nextInt();
        HashMap<String, String> base = new HashMap<>();
        ArrayList<HashMap<String, String>> layers = new ArrayList<>();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String op = next();
            HashMap<String, String> cur = layers.isEmpty() ? base : layers.get(layers.size() - 1);
            switch (op) {
                case "SET": {
                    String k = next(), v = next();
                    cur.put(k, v);
                    break;
                }
                case "DELETE":
                    cur.put(next(), DELETED);
                    break;
                case "GET": {
                    String k = next(), found = null;
                    for (int d = layers.size() - 1; d >= 0 && found == null; d--) found = layers.get(d).get(k);
                    if (found == null) found = base.get(k);
                    sb.append(found == null || found.equals(DELETED) ? "NULL" : found).append('\n');
                    break;
                }
                case "BEGIN":
                    layers.add(new HashMap<>());
                    break;
                case "ROLLBACK":
                    if (layers.isEmpty()) sb.append("NO TRANSACTION\n");
                    else layers.remove(layers.size() - 1);
                    break;
                case "COMMIT":
                    if (layers.isEmpty()) sb.append("NO TRANSACTION\n");
                    else {
                        HashMap<String, String> top = layers.remove(layers.size() - 1);
                        (layers.isEmpty() ? base : layers.get(layers.size() - 1)).putAll(top);
                    }
                    break;
                default:
                    break;
            }
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

const deleted = "\x00"

func main() {
	data, _ = io.ReadAll(os.Stdin)
	q := nextInt()
	base := map[string]string{}
	var layers []map[string]string
	current := func() map[string]string {
		if len(layers) == 0 {
			return base
		}
		return layers[len(layers)-1]
	}
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for i := 0; i < q; i++ {
		switch string(token()) {
		case "SET":
			k := string(token())
			current()[k] = string(token())
		case "DELETE":
			current()[string(token())] = deleted
		case "GET":
			k := string(token())
			v, ok := "", false
			for d := len(layers) - 1; d >= 0 && !ok; d-- {
				v, ok = layers[d][k]
			}
			if !ok {
				v, ok = base[k]
			}
			if !ok || v == deleted {
				v = "NULL"
			}
			out.WriteString(v)
			out.WriteByte('\n')
		case "BEGIN":
			layers = append(layers, map[string]string{})
		case "ROLLBACK":
			if len(layers) == 0 {
				out.WriteString("NO TRANSACTION\n")
			} else {
				layers = layers[:len(layers)-1]
			}
		case "COMMIT":
			if len(layers) == 0 {
				out.WriteString("NO TRANSACTION\n")
			} else {
				top := layers[len(layers)-1]
				layers = layers[:len(layers)-1]
				parent := current()
				for k, v := range top {
					parent[k] = v
				}
			}
		}
	}
}
